export const generateId = () => Math.random().toString(36).substr(2, 9);

// Fisher-Yates shuffle — returns a NEW array, never mutates original
export const shuffleArray = (arr) => {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
};

// Shuffle questions order + shuffle MCQ options per student
// Uses studentId as a seed concept — each call per student is stable within a session
export const randomizeExamForStudent = (questions, studentId) => {
  // Shuffle question order
  const shuffledQuestions = shuffleArray(questions);

  // For MCQ questions, shuffle options and remap correct_answer letter
  return shuffledQuestions.map((q) => {
    if (q.question_type !== 'MCQ' || !q.options) return q;

    const shuffledOptions = shuffleArray(q.options);

    // Find which new index has is_correct = true → that becomes the new correct letter
    const correctIndex  = shuffledOptions.findIndex((o) => o.is_correct);
    const correctLetter = ['A', 'B', 'C', 'D'][correctIndex];

    return {
      ...q,
      options:        shuffledOptions,
      correct_answer: correctLetter,
    };
  });
};

export const formatTime = (seconds) => {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
};

export const getGrade = (pct) => {
  if (pct >= 90) return { grade: 'A+', color: 'var(--success)' };
  if (pct >= 80) return { grade: 'A',  color: 'var(--success)' };
  if (pct >= 70) return { grade: 'B',  color: 'var(--accent2)' };
  if (pct >= 60) return { grade: 'C',  color: 'var(--warning)' };
  if (pct >= 50) return { grade: 'D',  color: 'var(--warning)' };
  return { grade: 'F', color: 'var(--danger)' };
};

export const hashPassword   = (p) => p; // swap for bcrypt in production
export const verifyPassword = (p, h) => p === h;

export const getPasswordStrength = (pwd) => {
  const checks = {
    length:    pwd.length >= 8,
    uppercase: /[A-Z]/.test(pwd),
    number:    /[0-9]/.test(pwd),
    special:   /[!@#$%^&*()_+\-=[\]{};':"\\|,.<>/?]/.test(pwd),
  };
  const passed = Object.values(checks).filter(Boolean).length;
  return { checks, passed, strong: passed === 4 };
};
